<template>
  <main class="mapping-workspace">
    <header class="workspace-header"><div class="identity"><button type="button" class="back-button" aria-label="返回课程生产" @click="goProduction"><ArrowLeft :size="18" /></button><div><p>教师空间 / 知识治理</p><h1>知识点—PPT 映射 <span>{{ courseTitle }}</span></h1><p v-if="courseMeta" class="course-meta">{{ courseMeta }}</p></div></div><div class="header-actions"><span v-if="hasPendingApply" class="unsaved"><CircleDot :size="15" />{{ pendingApplyLabel }}</span><button type="button" class="secondary" :disabled="loading" @click="load"><RefreshCw :size="16" />刷新</button><button type="button" class="primary" :disabled="applying || !canApply" @click="apply"><Check :size="16" />{{ applying ? '应用中…' : '应用到脚本' }}</button></div></header>
    <div v-if="error" class="page-error"><AlertTriangle :size="19" /><span>{{ error }}</span><button type="button" @click="load">重试</button></div>
    <div v-else class="governance-grid" :class="{ loading }">
      <aside class="nodes-panel"><div class="panel-heading"><div><p>课程知识点</p><small>{{ nodes.length }} 个节点</small></div><div class="tools"><button type="button" :disabled="working" @click="autoMap"><WandSparkles :size="15" />自动</button><button type="button" :disabled="working" @click="aiMap"><Sparkles :size="15" />AI 匹配</button></div></div><label class="search"><Search :size="16" /><input v-model.trim="query" placeholder="查找知识点" /></label><div v-if="loading" class="list-state"><LoaderCircle class="spin" :size="19" />加载映射数据…</div><div v-else-if="!filteredNodes.length" class="list-state">当前没有可治理的知识点。</div><div v-else class="node-list"><div v-for="node in filteredNodes" :key="node.node_id" class="node-row"><label class="batch-box" :for="`batch-${node.node_id}`"><input :id="`batch-${node.node_id}`" v-model="batchSelection" type="checkbox" :value="node.node_id" :aria-label="`选择 ${node.title || '未命名节点'} 进行批量编辑`" /><span class="sr-only">选择 {{ node.title || '未命名节点' }} 进行批量编辑</span></label><button type="button" :class="['node-select',{active:selectedId===node.node_id}]" :aria-pressed="selectedId===node.node_id" @click="selectNode(node.node_id)"><span class="node-index">{{ (node.node_index ?? 0) + 1 }}</span><span class="node-copy"><strong>{{ node.title || '未命名节点' }}</strong><small>{{ rangeText(node) }} · {{ confidenceText(node.confidence) }}</small></span><span class="mapping-state" :class="`state-${mappingState(node).tone}`">{{ mappingState(node).label }}</span></button></div></div></aside>
      <section class="pages-panel"><div class="panel-heading"><div><p>PPT 页面文本</p><small>{{ pages.length }} 页；点击页码调整当前节点范围</small></div><span v-if="selected" class="selection">{{ selected.title || '未命名节点' }}</span></div><div v-if="loading" class="page-state"><LoaderCircle class="spin" :size="20" />正在读取课件内容…</div><div v-else-if="!pages.length" class="page-state">尚未检测到可映射的 PPT 页面文本。请先完成资料解析或 PPT 生成。</div><div v-else class="page-list"><button v-for="page in pages" :key="page.page_no" type="button" :disabled="!selected" :class="['page-card',{selected:inDraftRange(page.page_no),clickable:selected}]" :aria-pressed="inDraftRange(page.page_no)" :aria-label="`将第 ${page.page_no} 页用于当前知识点映射`" @click="togglePage(page.page_no)"><span class="page-card-heading"><strong>第 {{ page.page_no }} 页</strong><span v-if="inDraftRange(page.page_no)">当前映射</span></span><span class="page-text">{{ page.text || '此页没有可用文本。' }}</span></button></div></section>
      <aside class="inspector"><div class="panel-heading"><div><p>映射检查</p><small>仅使用当前 Mapping API</small></div></div><template v-if="selected"><div class="selected-card"><p class="eyebrow">当前知识点</p><h2>{{ selected.title || '未命名节点' }}</h2><p class="preview">{{ selected.content_preview || '当前接口未提供内容摘要。' }}</p><dl><div><dt>来源</dt><dd>{{ selected.is_manual ? '教师手动调整' : '自动或 AI 候选' }}</dd></div><div><dt>匹配置信度</dt><dd>{{ confidenceText(selected.confidence) }}</dd></div></dl></div><fieldset class="range-editor"><legend>页面范围</legend><div><label>起始页<input v-model.number="draftStart" type="number" :min="1" :max="pageLimit" /></label><label>结束页<input v-model.number="draftEnd" type="number" :min="1" :max="pageLimit" /></label></div><p v-if="!validRange" class="validation"><AlertTriangle :size="14" />范围必须在现有 PPT 页码内，且结束页不小于起始页。</p><button type="button" class="secondary full" :disabled="working || !validRange || !dirtySelected" @click="saveSelected"><Save :size="16" />{{ working ? '保存中…' : '保存此映射' }}</button><button v-if="batchIds.size > 1" type="button" class="batch-save" :disabled="working || !validRange" @click="saveBatch">批量保存当前范围到 {{ batchIds.size }} 个知识点</button><p class="save-hint"><Info :size="15" />保存会写入已有映射接口；“应用到脚本”才会更新后续视频流程。</p></fieldset></template><div v-else class="select-prompt"><MousePointer2 :size="24" /><p>从左侧选择一个知识点，检查其 PPT 页面范围与匹配置信度。</p></div><div class="boundary"><Info :size="16" /><p>Evidence 原文高亮、图谱关系和影响分析尚未具备正式接口，因此没有在本页面伪造为已实现能力。</p></div></aside>
    </div>
  </main>
</template>

<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { AlertTriangle, ArrowLeft, Check, CircleDot, Info, LoaderCircle, MousePointer2, RefreshCw, Save, Search, Sparkles, WandSparkles } from 'lucide-vue-next'
import { getCourseWorkspaceContext } from '@/api/course_workspace.js'
import { aiMatchMapping, applyMapping, autoGenerateMapping, batchUpdateMapping, getMappingDetail, updateNodeMapping } from '@/api/mapping.js'
import { showToast } from '@/utils/toast.js'
const route=useRoute();const router=useRouter();const courseId=computed(()=>route.params.courseId);const courseContext=ref(null);const loading=ref(false);const working=ref(false);const applying=ref(false);const error=ref('');const data=ref({nodes:[],pages:[]});const selectedId=ref(null);const query=ref('');const draftStart=ref(1);const draftEnd=ref(1);const batchSelection=ref([])
const nodes=computed(()=>data.value.nodes||[]);const pages=computed(()=>data.value.pages||[]);const courseTitle=computed(()=>courseContext.value?.course?.title||`课程 #${courseId.value}`);const courseMeta=computed(()=>{const course=courseContext.value?.course;if(!course)return '';const parts=[];if(nodes.value.length)parts.push(`${nodes.value.length} 个知识点`);if(course.total_pages)parts.push(`${course.total_pages} 页资料`);return parts.join(' · ')});const selected=computed(()=>nodes.value.find(node=>node.node_id===selectedId.value)||null);const batchIds=computed(()=>new Set(batchSelection.value));const filteredNodes=computed(()=>{const term=query.value.toLowerCase();return term?nodes.value.filter(n=>String(n.title||'').toLowerCase().includes(term)):nodes.value});const pageLimit=computed(()=>Math.max(1,Number(courseContext.value?.course?.total_pages)||0,...pages.value.map(page=>Number(page.page_no)||0)));const scriptRanges=computed(()=>new Map((courseContext.value?.nodes||[]).map(node=>[node.id,{start:Number(node.page_start),end:Number(node.page_end)}])));const scriptRangesKnown=computed(()=>Array.isArray(courseContext.value?.nodes));const pendingApplyCount=computed(()=>scriptRangesKnown.value?nodes.value.filter(node=>{const scriptRange=scriptRanges.value.get(node.node_id);return !scriptRange||scriptRange.start!==Number(node.page_start)||scriptRange.end!==Number(node.page_end)}).length:0);const hasPendingApply=computed(()=>pendingApplyCount.value>0);const pendingApplyLabel=computed(()=>pendingApplyCount.value+' 项待应用');const canApply=computed(()=>scriptRangesKnown.value?hasPendingApply.value:nodes.value.some(node=>mappingState(node).tone!=='danger'));const validRange=computed(()=>Number.isInteger(draftStart.value)&&Number.isInteger(draftEnd.value)&&draftStart.value>=1&&draftEnd.value>=draftStart.value&&draftEnd.value<=pageLimit.value);const dirtySelected=computed(()=>selected.value&& (draftStart.value!==selected.value.page_start||draftEnd.value!==selected.value.page_end))
function goProduction(){router.push(`/teacher/course/${courseId.value}/production`)}function mappingState(node){const start=Number(node.page_start);const end=Number(node.page_end);if(!Number.isFinite(start)||!Number.isFinite(end)||start<1||end<start)return {tone:'danger',label:'未映射'};if(node.is_manual)return {tone:'success',label:'已确认'};const confidence=Number(node.confidence);if(Number.isFinite(confidence)&&confidence<0.65)return {tone:'warning',label:'待检查'};return {tone:'info',label:'候选映射'}}function rangeText(node){return `PPT ${node.page_start || '?'}–${node.page_end || '?' }页`}function confidenceText(value){const numeric=Number(value);return Number.isFinite(numeric)?`置信度 ${Math.round(numeric*100)}%`:'置信度未提供'}function selectNode(id){selectedId.value=id}function inDraftRange(pageNo){return selected.value&&pageNo>=draftStart.value&&pageNo<=draftEnd.value}function togglePage(pageNo){if(!selected.value)return;if(pageNo<draftStart.value)draftStart.value=pageNo;else if(pageNo>draftEnd.value)draftEnd.value=pageNo;else {draftStart.value=pageNo;draftEnd.value=pageNo}}
watch(selected,(node)=>{if(node){draftStart.value=node.page_start||1;draftEnd.value=node.page_end||draftStart.value;if(!batchSelection.value.includes(node.node_id))batchSelection.value=[...batchSelection.value,node.node_id]}})
async function load(){loading.value=true;error.value='';try{const [result,context]=await Promise.all([getMappingDetail(courseId.value),getCourseWorkspaceContext(courseId.value).catch(()=>null)]);data.value={nodes:result?.nodes||[],pages:result?.pages||[]};courseContext.value=context;if(!selectedId.value&&data.value.nodes.length)selectedId.value=data.value.nodes[0].node_id}catch{error.value='映射数据暂时无法读取。请检查课程是否已经解析，并确认当前教师有访问权限。'}finally{loading.value=false}}
async function runGenerator(fn,label){working.value=true;try{await fn(courseId.value);showToast(`${label}已完成，请检查候选结果后再应用到脚本。`,'success');await load()}catch{showToast(`${label}失败，请稍后重试。`,'error')}finally{working.value=false}}function autoMap(){runGenerator(autoGenerateMapping,'自动映射')}function aiMap(){runGenerator(aiMatchMapping,'AI 匹配')}
async function persistMappings(nodeIds){if(!validRange.value||!nodeIds.length)return;working.value=true;try{const updates=nodeIds.map(node_id=>({node_id,page_start:draftStart.value,page_end:draftEnd.value}));if(updates.length===1){const update=updates[0];await updateNodeMapping(courseId.value,update.node_id,update.page_start,update.page_end)}else await batchUpdateMapping(courseId.value,updates);const updateByNode=new Map(updates.map(update=>[update.node_id,update]));data.value.nodes=data.value.nodes.map(node=>{const update=updateByNode.get(node.node_id);return update?{...node,...update,is_manual:true,confidence:1}:node});showToast(updates.length===1?'映射已保存，尚未应用到脚本。':updates.length+' 条映射已保存，尚未应用到脚本。','success')}catch{showToast('保存映射失败。当前页码范围仍保留，可修改后重试。','error')}finally{working.value=false}}function saveSelected(){if(selected.value)persistMappings([selected.value.node_id])}function saveBatch(){persistMappings([...batchIds.value])}
async function apply(){applying.value=true;try{await applyMapping(courseId.value);await load();showToast('映射已应用到脚本。后续视频生成将使用新的页面范围。','success')}catch{showToast('应用失败：请先完成至少一条有效映射后重试。','error')}finally{applying.value=false}}
onMounted(load)
</script>

<style scoped>
