#64748b;font-size:12px;margin-top:3px}.tools{display:flex;gap:5px}.tools button{border:0;background:#eff6ff;color:#1769aa;border-radius:7px;padding:6px;display:flex;cursor:pointer}.tools button:disabled{opacity:.55;cursor:not-allowed}.search{margin:14px 0 10px;height:36px;border:1px solid #cbd5e1;border-radius:8px;display:flex;align-items:center;padding:0 9px;gap:6px;color:#64748b}.search input{border:0;outline:0;min-width:0;flex:1;font-size:13px}.node-list{overflow:auto;max-height:calc(100dvh - 185px);display:flex;flex-direction:column;gap:4px}.node-row{display:grid;grid-template-columns:18px minmax(0,1fr);gap:5px;align-items:center}.node-select{border:0;border-radius:8px;padding:9px;width:100%;background:transparent;display:grid;grid-template-columns:20px 1fr auto;gap:7px;text-align:left;cursor:pointer;color:#334155;font:inherit}.node-select:hover{background:#f8fafc}.node-select.active{background:#e8f1f8;color:#0b5f97}.node-index{font-size:12px;color:#64748b;padding-top:2px}.node-copy{min-width:0}.node-copy strong,.node-copy small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.node-copy strong{font-size:13px}.node-copy small{font-size:11px;color:#64748b;margin-top:4px}.batch-box{width:18px;height:18px;display:grid;place-items:center;cursor:pointer}.batch-box input{width:14px;height:14px;cursor:pointer}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.mapping-state{font-size:10px;height:max-content;border-radius:4px;padding:3px 4px;white-space:nowrap}.state-success{background:#dcfce7;color:#166534}.state-warning{background:#fffbeb;color:#a16207}.state-info{background:#eff6ff;color:#1769aa}.state-danger{background:#fef2f2;color:#b91c1c}.list-state,.page-state{min-height:150px;display:flex;align-items:center;justify-content:center;gap:7px;color:#64748b;font-size:13px;text-align:center;padding:16px}.pages-panel .panel-heading{padding:16px;border-bottom:1px solid #e2e8f0}.selection{font-size:12px;max-width:40%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#1769aa;background:#eff6ff;padding:4px 7px;border-radius:5px}.page-list{padding:14px;overflow:auto;display:grid;gap:10px}.page-card{border:1px solid #e2e8f0;border-radius:9px;padding:13px;transition:background 160ms,border-color 160ms;text-align:left;background:#fff;color:#1e293b;font:inherit}.page-card.clickable{cursor:pointer}.page-card.clickable:hover{border-color:#93c5fd}.page-card:disabled{cursor:not-allowed;opacity:.72}.page-card.selected{border-color:#1769aa;background:#eff6ff;box-shadow:inset 3px 0 #1769aa}.page-card-heading{display:flex;justify-content:space-between;gap:8px;font-size:13px}.page-card-heading span{font-size:11px;color:#1769aa}.page-text{display:block;margin:8px 0 0;color:#475569;line-height:1.65;font-size:13px;white-space:pre-line}.selected-card{margin-top:18px}.selected-card h2{font-size:17px;margin:4px 0 8px}.preview{font-size:13px;line-height:1.55;color:#475569;margin:0}.selected-card dl{margin:14px 0 0;display:grid;gap:8px}.selected-card dl div{padding:8px;background:#f8fafc;border-radius:7px}.selected-card dt{font-size:11px;color:#64748b}.selected-card dd{font-size:13px;margin:3px 0 0}.range-editor{border:0;padding:0;margin:18px 0}.range-editor legend{font-size:13px;font-weight:700;margin-bottom:9px}.range-editor>div{display:grid;grid-template-columns:1fr 1fr;gap:8px}.range-editor label{font-size:12px;color:#475569}.range-editor input{box-sizing:border-box;margin-top:4px;width:100%;height:36px;border:1px solid #cbd5e1;border-radius:7px;padding:0 8px;font-size:14px}.full{width:100%;margin-top:12px}.batch-save{width:100%;min-height:38px;margin-top:8px;border:1px solid #1769aa;background:#eff6ff;color:#1769aa;border-radius:8px;font-size:12px;font-weight:600;cursor:pointer}.save-hint{font-size:12px;color:#64748b;display:flex;gap:5px;line-height:1.45}.validation{font-size:12px;color:#b91c1c;display:flex;gap:5px;line-height:1.4}.select-prompt{min-height:220px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;color:#64748b;gap:9px;font-size:13px;line-height:1.55}.select-prompt p{margin:0}.boundary{border-top:1px solid #e2e8f0;padding-top:13px;display:flex;gap:7px;color:#475569;font-size:12px;line-height:1.5}.boundary p{margin:0}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}button:focus-visible,input:focus-visible{outline:3px solid #93c5fd;outline-offset:2px}button:disabled{opacity:.55;cursor:not-allowed}@media(max-width:1180px){.governance-grid{grid-template-columns:230px minmax(0,1fr)}.inspector{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:16px}.inspector>.panel-heading{grid-column:1/-1}.boundary{margin-top:18px}}@media(max-width:760px){.workspace-header{padding:10px 14px;align-items:flex-start;flex-direction:column}.header-actions{width:100%;justify-content:flex-end}.governance-grid{grid-template-columns:1fr;padding:10px}.nodes-panel{max-height:330px}.node-list{max-height:220px}.pages-panel{min-height:440px}.inspector{grid-column:auto;display:block}.inspector>.panel-heading{display:block}}@media(max-width:440px){.header-actions{justify-content:stretch}.header-actions button{flex:1}.unsaved{display:none}.range-editor>div{grid-template-columns:1fr}.identity h1{font-size:16px}}
</style>
